      '彼女が生きたのは、ローマがどんどん地中海を飲みこんでいく時代。エジプトは独立を保っていたけど、いつローマに併合されてもおかしくなかった。そこで彼女がとった作戦は、ローマの最有力者と手を結ぶことだった。弟との王位争いで追い出されていた彼女は、エジプトに来たカエサルに近づき、その支援で女王の座を取りもどした。二人のあいだには息子カエサリオンも生まれた。',
      'カエサルが暗殺されると、次に手を組んだのはカエサルの部下アントニウス。アントニウスはエジプトを拠点にして、ローマの東半分を治めるようになった。でもこれはローマの人びとから見ると「外国の女王にあやつられている」と映った。カエサルの養子オクタウィアヌスは、これを宣伝に使って二人と対決することになる。',
      '前31年、ギリシア西岸のアクティウムの海戦で、クレオパトラとアントニウスの艦隊は敗れた。アントニウスは自殺し、クレオパトラも翌年、ローマの凱旋式で見せ物にされることをこばんで命を絶った。毒蛇にかませたという話が有名だけど、本当の方法ははっきりしない。こうして約300年続いたプトレマイオス朝は終わり、エジプトはローマの領土になった。'
