      { title: '「クレオパトラの鼻」', text: '「クレオパトラの鼻がもう少し低かったら、世界の歴史は変わっていただろう」は、17世紀フランスの思想家パスカルの言葉。古代の記録では、彼女の魅力は美しさより話のうまさや知性にあったと書かれている。' }
