      '後漢の末、宦官と官僚の争いで政治は乱れ、184年には宗教結社太平道による黄巾の乱が起きた。曹操はその鎮圧で頭角をあらわし、やがて群雄の一人となる。196年、彼は行き場を失っていた後漢最後の皇帝献帝を、自分の本拠地の許に迎えた。皇帝の名で命令を出せる立場を手に入れたんだ。同じころ、土地を失った農民や兵士に土地を耕させる屯田制を始め、食料を確保した。',
