      '高宗は病気がちで、やがて政治の多くを皇后がとりしきるようになった。高宗の死後も、彼女は息子たちを次々に皇帝に立てては退け、実権を手放さない。そして690年、ついに自分が皇帝となり、国号を唐から「周」に改めた。皇帝は男性という常識を正面からくつがえしたわけだ。反対する皇族や貴族はきびしく処罰し、密告を奨励したので、恐怖政治だと言われることも多い。',
