      { title: 'イブン=ハルドゥーンとの会見', text: '1401年、ダマスクスを包囲したティムールは、歴史家イブン=ハルドゥーンと会見し、北アフリカの地理や歴史について熱心に質問したという。この会見は本人の記録に残っている。' }
