      '彼の準備はとても周到だった。まずボスポラス海峡のヨーロッパ側に、わずか4か月ほどで要塞を築き、黒海からの援軍の道を断った。さらにハンガリー出身の技術者ウルバンに、巨大な大砲をつくらせた。何百キロもある石の弾を撃ちこんで、それまでどんな軍も破れなかった城壁をくずしていったんだ。',
