      '1526年、モハーチの戦いでハンガリー王国を破り、1529年には神聖ローマ帝国の重要拠点ウィーンを包囲した。ウィーンは落とせなかったけれど、ヨーロッパの人びとは大きな恐怖を感じた。このとき、神聖ローマ皇帝カール5世と対立していたフランス王フランソワ1世は、なんとキリスト教国なのにオスマン帝国と手を組んでいた。宗教より国の利益を優先する、近世の国際政治の始まりだ。',
