    legacy: 'コロンブスの航海によって、ヨーロッパとアメリカ大陸がつながり、作物・動物・病気・人びとが大西洋をこえて行き交う「コロンブス交換」が始まった。それは世界の一体化を進めた一方、先住民社会の破壊と、のちの奴隷貿易の拡大をもたらした。',
    terms: ['大航海時代', 'イサベル', 'サンサルバドル島', 'インディオ', 'アメリゴ=ヴェスプッチ', 'コロンブス交換', 'エンコミエンダ制']
