      'ルイ14世は、わずか4歳でフランス王になった。在位72年は、ヨーロッパの君主でも最長クラスの記録だ。子どものころ、彼は「フロンドの乱」を経験している。貴族やパリの人びとが王権に反発して起こした反乱で、少年王は夜中にパリから逃げ出さなければならなかった。このときの恐怖と屈辱が、「二度と貴族に逆らわせない」という彼の決意につながったといわれる。',
      '宰相マザランが亡くなると、22歳のルイは「これからは私が自分で政治をする」と宣言した。王の権力は神から授けられたもので、だれにも制限されないという王権神授説のもとで、絶対王政の頂点を築いた。財務総監コルベールは、国内の産業を育てて輸出を増やし、輸入をおさえる重商主義政策をとり、王の財政を支えた。',
      'ルイ14世を象徴するのが、パリ郊外のヴェルサイユ宮殿だ。もとは狩りのための小さな館だったのを、巨大な宮殿と庭園につくりかえ、1682年に宮廷と政府を移した。ここに大貴族たちを住まわせ、王の起床から就寝までの儀式に参加させた。王のそばに仕えることが名誉となり、貴族は反乱を起こすどころか、王の機嫌をとることに必死になった。豪華な宮廷文化は、ヨーロッパ中の王侯のあこがれになった。',
      'でも、栄光にはお金がかかった。ルイは領土を広げるために何度も戦争を起こし、最後のスペイン継承戦争では、孫をスペイン王にすることには成功したものの、国の財政はぼろぼろになった。また、ナントの王令を廃止してプロテスタント（ユグノー）の信仰を禁じたため、多くの商工業者が国外に逃げてしまった。死の床でルイは、ひ孫に「私は戦争を好みすぎた」と語ったと伝えられる。'
