      '1697年、彼は250人あまりの大使節団を西ヨーロッパに送り出した。驚くのは、皇帝自身が「ピョートル=ミハイロフ」という偽名で一行にまぎれこんだこと。オランダでは造船所で船大工として働き、イギリスでも造船所や工場、天文台を見学した。もっとも、2メートルの大男だから、正体はすぐにばれていたらしい。彼は技術者や職人をたくさん雇って帰国した。',
      '帰国すると、ピョートルは改革に取りかかった。貴族の長いあごひげを自分ではさみで切ったという話は有名だ。ひげをのばしたい人には「ひげ税」をかけた。軍隊を西ヨーロッパ式に改め、海軍をつくり、工場を建て、役人の位を能力に応じて決める官等表を定めた。ロシアを、上からの力で一気にヨーロッパの強国にしようとしたんだ。',
