      { title: 'ホッブズとのちがい', text: '同じ社会契約説でも、ホッブズは『リヴァイアサン』で、自然のままでは「万人の万人に対する闘争」になるので、強い主権者に権利をゆだねるべきだと説いた。ロックは、権利をゆだねても抵抗権は残る、と考えた。' }
