      'ケンブリッジ大学の学生だった1665年、ペストが大流行して大学が閉鎖された。故郷に帰ったニュートンは、約1年半のあいだに、微分積分の考え方、プリズムによる光の研究、そして万有引力のアイデアという、科学の歴史を変える3つの大発見の基礎を築いた。この時期は「驚異の年」とよばれている。家にこもっていた時間が、とんでもない成果を生んだわけだ。',
