      '転機は1819年。ボリバルは軍を率いて、雪におおわれたアンデス山脈をこえるという大胆な作戦に出た。寒さで多くの兵士を失いながらも、山をこえて敵の背後をつき、ボヤカの戦いで大勝した。こうして今のコロンビア・ベネズエラ・エクアドルなどをふくむ「大コロンビア」が生まれた。さらに南へ進み、部下のスクレがペルーのスペイン軍をアヤクーチョで破り、南アメリカの独立はほぼ決定的になった。',
      'ボリバルの夢は、独立した国々がまとまって、大きな連合をつくることだった。1826年にはパナマで、アメリカ大陸の国々の会議も開いた。でも、各地の有力者たちは自分の地域の利益を優先し、大コロンビアは内部の対立で分裂していく。失意の彼は1830年に病で亡くなった。それでも南アメリカでは、今も彼は「解放者」として深く敬われ、ボリビアの国名やベネズエラの通貨の名に、その名が残っている。'
