    legacy: 'ボリバルの戦いによって、南アメリカ北部のスペイン植民地は独立を果たした。中南米の統合をめざした彼の理想は実現しなかったが、のちのラテンアメリカの連帯をめざす運動の象徴として受けつがれている。',
