      'スカルノは、オランダの植民地だったインドネシア（オランダ領東インド）のジャワ島で生まれた。父はジャワ人の教師、母はバリ島の出身だった。バンドンの工業大学で建築を学んで技師になったが、独立運動に身を投じ、1927年にインドネシア国民党を結成する。何万もの島に、さまざまな言葉や宗教をもつ人びとが住むこの地域を、「インドネシア」という一つの国民としてまとめようとしたんだ。',
